/** Find a single repair line item by ID. */
async function repoFindLineItemById(id: string): Promise<typeof repairLineItems.$inferSelect | undefined> {
  const [result] = await db
    .select()
    .from(repairLineItems)
    .where(eq(repairLineItems.id, id))

